    # The repeated strip gives the ordered colors for the copies.
    seq = None
    for r in range(h - 1):
        if grid[r] == grid[r + 1]:
            row = grid[r]
            c = 0
            while c < w:
                if row[c] == 0:
                    c += 1
                    continue
                end = c
                while end < w and row[end] != 0:
                    end += 1
                run = row[c:end]
                if len(run) > 1 and len(set(run)) == len(run):
                    seq = run
                    break
                c = end
            if seq:
                break

    if not seq:
        return grid

    # Find the largest 8-connected component among the strip's colors.
    components = []
    for color in set(seq):
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, cc + dc
                            if (0 <= nr < h and 0 <= nc < w
                                and grid[nr][nc] == color
                                and (nr, nc) not in seen):
                                seen.add((nr, nc))
                                stack.append((nr, nc))
                components.append((color, comp))

    color, comp = max(components, key=lambda x: len(x[1]))
    r0 = min(r for r, c in comp)
    c0 = min(c for r, c in comp)
    shape = [(r - r0, c - c0) for r, c in comp]
    shape_h = max(dr for dr, dc in shape) + 1
    idx = seq.index(color)

    out = [[0] * w for _ in range(h)]
    first_top = r0 - idx * shape_h
    for i, new_color in enumerate(seq):
        top = first_top + i * shape_h
        for dr, dc in shape:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = new_color
    return out
